  ["highground.coachpreferences.these_dimensions_and_row_details_belong_to.538aec"] = "Estas dimensiones y detalles de fila pertenecen a Battlegrounds. Arena y Nearby tienen páginas de apariencia independientes.",
  ["highground.coachpreferences.bar_textures_colours_and_borders_are_shared.cbec37"] = "Se comparten las texturas, los colores y los bordes de las barras. Ajuste el tamaño de cada panel en la página de apariencia de su propio complemento.",
  ["highground.coachpreferences.settings_live_with_their_addon.f2c359"] = "Configuración en vivo con su complemento",
  ["highground.coachpreferences.use_an_addon_s_settings_appearance_commands.b1a987"] = "Utilice las páginas de configuración, apariencia, comandos, vistas previas y guías de un complemento. Los paneles de campo de batalla usan /hg bg test. Ejecute /hg test o /hg test stop desde Ayuda y comandos para alternar o detener todas las vistas previas. Resumen y habilitar controles si el complemento se ejecuta después de recargar. Las preferencias compartidas afectan a todos los complementos.",
  ["highground.coachpreferences.keep_the_panels_you_want.abbf0b"] = "Mantenga los paneles que desee",
  ["highground.coachpreferences.choose_shared_preferences.f69dd0"] = "Elegir preferencias compartidas",
  ["highground.coachpreferences.checked_means_enabled_all_available_feature_switches.16b69f"] = "Seleccionado significa habilitado. Aquí se muestran todos los interruptores de función disponibles; desplácese para ver el resto.",
