  ["highground.coachpreferences.choose_the_warnings_you_want.2794f4"] = "Elige las alertas que quieras",
  ["highground.coachpreferences.essentials_is_a_starting_point_text_only.1f45b3"] = "Essentials es un punto de partida. El texto solo mantiene las alertas escritas y silencia los sonidos de alerta.",
  ["highground.coachpreferences.this_changes_your_real_alert_preference.ecd3f5"] = "Esto cambia tu preferencia de alerta real.",
