  ["highground.coachpreferences.the_battlegrounds_nearby_and_bounties_links_open.676c0b"] = "Los enlaces Campos de batalla, Cercanos y Recompensas abren sus controles de texto y sonido directamente. Los complementos deshabilitados estarán disponibles después de habilitarlos en Addons y recargarlos.",
  ["highground.coachpreferences.click_battlegrounds_or_next_to_open_its.68ede3"] = "Haz clic en Battlegrounds o Siguiente para abrir los controles de alerta.",
  ["highground.coachpreferences.enemy_stealth_stays_available_here_even_when.63bf57"] = "El sigilo enemigo permanece disponible aquí incluso cuando un complemento está deshabilitado.",
  ["highground.coachpreferences.choose_text_sound_or_both.306e9e"] = "Elige texto, sonido o ambos",
  ["highground.coachpreferences.these_switches_belong_to_battlegrounds_settings_nearby.0373c0"] = "Estos interruptores pertenecen a la configuración de Battlegrounds. Cerca y recompensas tienen sus propias. El nivel de alerta compartido y el sonido maestro siguen aplicándose.",
  ["highground.coachpreferences.enemy_stealth_applies_across_addons_other_alert.fa92cd"] = "El sigilo enemigo se aplica a todos los complementos. Otras categorías de alerta viven en la configuración de su complemento. El nivel de alerta compartido y el sonido maestro siguen aplicándose.",
  ["highground.coachpreferences.highground_is_the_only_download_you_need.f138df"] = "Highground es la única descarga que necesitas",
  ["highground.coachpreferences.addons_brings_the_addon_switches_settings_shortcuts.df8aff"] = "Addons reúne los interruptores de complementos, los accesos directos de configuración y las guías. Elimine cualquier descarga independiente separada. Mantenga cada carpeta de módulo y ambos complementos de datos requeridos. Desactivar un complemento de datos detiene la carga de Highground.",
  ["highground.coachpreferences.a_disabled_module_does_not_activate_a.e4cf84"] = "Un módulo deshabilitado no activa una copia independiente. Nada es eliminado por esta guía.",
  ["highground.coachpreferences.choose_which_addons_run.892aae"] = "Elige qué complementos ejecutar",
  ["highground.coachpreferences.enable_addon_is_the_same_per_character.e05474"] = "Enable addon es el mismo interruptor por carácter que WoW's AddOn List. Los seis subaddons están incluidos en la descarga Highground.",
  ["highground.coachpreferences.these_are_real_switches_you_can_continue.862243"] = "Estos son interruptores reales. Puedes continuar sin cambiar nada.",
